const catalog={market:[{icon:'🥫',name:'Trail rations',desc:'A meal restores 35 vitality',price:8,item:'food'},{icon:'🔋',name:'Ammo bundle',desc:'8 rounds for your found weapons',price:12,item:'ammo'},{icon:'🧃',name:'Energy tonic',desc:'Restore 45 stamina',price:7,item:'stamina'}],pharmacy:[{icon:'🩹',name:'Medkit',desc:'Restore 55 vitality',price:14,item:'med'},{icon:'💉',name:'Field dressing',desc:'Restore 25 vitality',price:7,item:'bandage'},{icon:'🧪',name:'Adrenal shot',desc:'Restore 60 stamina',price:9,item:'stamina'}]};
function openShop(shop){if(!shop){toast('Get closer to a shop to trade');return}paused=true;const isMarket=shop.type==='market';$('#shoplabel').textContent=isMarket?'SAFE ZONE · MARKET':'SAFE ZONE · PHARMACY';$('#shopname').textContent=isMarket?'The Corner Store':'Field Pharmacy';$('#shopcopy').textContent=isMarket?'Trade with Mara before the sun drops. Supplies keep you moving; ammo keeps them down.':'Jules has patched up half the valley. Keep your health above zero.';$('#shopcoins').textContent=world.coins;$('#goods').innerHTML='';catalog[shop.type].forEach(item=>{const row=document.createElement('div');row.className='good';row.innerHTML=`<span class="emoji">${item.icon}</span><div class="desc"><strong>${item.name}</strong><small>${item.desc} · ¢${item.price}</small></div><button class="buy" ${world.coins<item.price?'disabled':''}>BUY</button>`;row.querySelector('button').onclick=()=>buy(item,shop);$('#goods').append(row)});$('#shop').classList.add('open')}
function buy(item,shop){if(world.coins<item.price)return;world.coins-=item.price;if(item.item==='food'){world.food++;updateHud();toast('Trail rations added to your pack')}else if(item.item==='ammo'){world.ammo+=8;updateHud();toast('Ammo secured: +8 rounds')}else if(item.item==='stamina'){world.stamina=clamp(world.stamina+60,0,100);updateHud();toast('Feeling steadier')}else if(item.item==='med'){world.hp=clamp(world.hp+55,0,100);updateHud();toast('Patch yourself up')}else{world.hp=clamp(world.hp+25,0,100);updateHud();toast('Bandage applied')}openShop(shop)}
function nearShop(){let best=null,dist=99;for(const s of world.shops){let d=Math.hypot(player.position.x-s.x,player.position.z-s.z);if(d<dist){best=s;dist=d}}return dist<5.4?best:null}
function interact(){let s=nearShop();if(s)openShop(s);else if(world.food>0&&world.hp<94){world.food--;world.hp=clamp(world.hp+35,0,100);toast('Rations eaten · +35 vitality');updateHud()}else toast('No shop nearby · find a storefront')}
function closeShop(){$('#shop').classList.remove('open');paused=false}
$('#closeShop').onclick=closeShop;$('#shop').addEventListener('pointerdown',e=>{if(e.target===$('#shop'))closeShop()});
function updateHud(){const h=Math.round(world.hp);$('#hptext').textContent=`${h} / 100`,$('#hpbar').style.width=h+'%';$('#sttext').textContent=Math.round(world.stamina)+'%';$('#stbar').style.width=world.stamina+'%';$('#coins').textContent=world.coins;$('#shopcoins').textContent=world.coins;$('#foodcount').textContent=world.food;$('#shotcount').textContent=world.shotgun;$('#riflecount').textContent=world.rifle;$('#slot1').style.opacity=world.shotgun?'1':'.48';$('#slot2').style.opacity=world.rifle?'1':'.48';$('#biome').innerHTML=(biomeAt(player.position.x,player.position.z)==='Pinewood'?'🌲':biomeAt(player.position.x,player.position.z)==='Ashlands'?'🌋':'🌿')+' <b>'+biomeAt(player.position.x,player.position.z)+'</b>';for(let i=0;i<4;i++)$('#slot'+i).classList.toggle('active',world.active===i)}
let toastTimer;function toast(text){const t=$('#toast');t.textContent=text;t.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.remove('show'),1900)}
function setWeapon(n){world.active=n;if(n===1&&!world.shotgun){toast('No shotgun yet · find a police zombie');world.active=0}if(n===2&&!world.rifle){toast('No rifle yet · find a military zombie');world.active=0}if(n===3&&world.food<1){toast('No rations left');world.active=0}updateHud()}
function attack(){if(!gameStarted||dead||paused)return;if(world.active===3){if(world.food>0){world.food--;world.hp=clamp(world.hp+35,0,100);world.stamina=clamp(world.stamina+15,0,100);toast('Rations eaten · +35 vitality');updateHud()}else toast('Out of rations');return}if(world.active===1||world.active===2){if(!world.shotgun&&!world.rifle){toast('Find a special infected to get a firearm');setWeapon(0);return}if(world.ammo<=0){toast('Out of ammo · visit the Corner Store');return}world.ammo--;let range=world.active===1?15:21;let target=closestZombie(range);world.playerAttack=.35;if(target){damageZombie(target,world.active===1?48:38);if(world.active===1){for(let z of world.zombies)if(Math.hypot(z.position.x-target.position.x,z.position.z-target.position.z)<3)damageZombie(z,22)}}else toast('Shot missed · move closer');updateHud();return}
 if(player.userData.attackCooldown>0)return;player.userData.attackCooldown=.48;player.rotation.y+=Math.PI;setTimeout(()=>{if(player)player.rotation.y-=Math.PI},120);let target=closestZombie(3.2);if(target){damageZombie(target,30);player.userData.attackCooldown=.7}else toast('Nothing in reach')}
function closestZombie(range){let t=null,best=range;for(const z of world.zombies){let d=Math.hypot(z.position.x-player.position.x,z.position.z-player.position.z);if(d<best){best=d;t=z}}return t}
function damageZombie(z,amount){if(!z||z.userData.dead)return;z.userData.hp-=amount;z.scale.set(1.13,.91,1.13);setTimeout(()=>{if(z.parent&&!z.userData.dead)z.scale.set(1,1,1)},100);if(z.userData.hp<=0){z.userData.dead=true;let type=z.userData.type;scene.remove(z);world.zombies=world.zombies.filter(v=>v!==z);world.kills++;world.coins+=type==='military'?6:type==='police'?4:2;toast(type==='military'?'Military infected down · +¢6':type==='police'?'Officer down · +¢4':'Infected down · +¢2');if(type==='police'&&Math.random()<.32)drop('shotgun',z.position.x,z.position.z);if(type==='military'&&Math.random()<.31)drop('rifle',z.position.x,z.position.z);if(Math.random()<.22)drop('food',z.position.x,z.position.z);updateHud()}}
function pickup(){for(let i=world.drops.length-1;i>=0;i--){let d=world.drops[i];if(Math.hypot(player.position.x-d.x,player.position.z-d.z)<1.6){if(d.type==='shotgun'){world.shotgun=1;world.active=1;toast('POLICE SHOTGUN · weapon unlocked')}else if(d.type==='rifle'){world.rifle=1;world.active=2;toast('ASSAULT RIFLE · weapon unlocked')}else{world.food++;toast('Rations salvaged')}scene.remove(d.group);world.drops.splice(i,1);updateHud()}}}
function update(dt){if(!gameStarted||dead||paused)return;world.elapsed+=dt;world.time=(world.time+dt/126)%1;let hour=Math.floor(world.time*24),minute=Math.floor((world.time*24-hour)*60);$('#clock').textContent=`DAY ${String(world.day).padStart(2,'0')} · ${String(hour).padStart(2,'0')}:${String(minute).padStart(2,'0')}`;let night=(hour>=19||hour<6);if(night!==world.night){world.night=night;if(night){$('#wave').textContent='THE DEAD ARE WAKING';$('#wave').classList.add('on');setTimeout(()=>$('#wave').classList.remove('on'),2600);toast('Nightfall · stay alert')}else{world.day++;$('#wave').textContent='DAWN BREAKS';$('#wave').classList.add('on');setTimeout(()=>$('#wave').classList.remove('on'),2300);world.zombies.filter(()=>Math.random()<.62).forEach(z=>{scene.remove(z);world.zombies=world.zombies.filter(v=>v!==z)});toast('Dawn · the dead thin out')}}
 let dark=night?1:hour<7?clamp((7-hour)/2,0,.8):hour>17?clamp((hour-17)/2,0,.85):0;scene.background.set(dark?'#273b50':'#a9c5b7');scene.fog.color.set(dark?'#26394a':'#9ab7a8');scene.fog.density=dark?.017:.012;world.sun.intensity=dark?0.65:3;world.sun.color.set(dark?'#8aa9dc':'#fff0ce');
 const dx=(keys.KeyD||keys.ArrowRight?1:0)-(keys.KeyA||keys.ArrowLeft?1:0)+moveVec.x,dz=(keys.KeyS||keys.ArrowDown?1:0)-(keys.KeyW||keys.ArrowUp?1:0)+moveVec.y;let len=Math.hypot(dx,dz);if(len>0){let speed=keys.ShiftLeft&&world.stamina>0?7.2:4.7;if(speed>5){world.stamina=clamp(world.stamina-dt*18,0,100)}else world.stamina=clamp(world.stamina+dt*9,0,100);let nx=player.position.x+dx/len*speed*dt,nz=player.position.z+dz/len*speed*dt;if(Math.abs(nx)<32&&!blocked(nx,player.position.z))player.position.x=nx;if(Math.abs(nz)<32&&!blocked(player.position.x,nz))player.position.z=nz;player.rotation.y=Math.atan2(dx,dz)}else world.stamina=clamp(world.stamina+dt*12,0,100);
 if(world.night&&world.elapsed-world.lastSpawn>2.7&&world.zombies.length<22){spawnZombie();world.lastSpawn=world.elapsed}if(!world.night&&world.zombies.length<3&&world.elapsed-world.lastSpawn>8){spawnZombie();world.lastSpawn=world.elapsed}
 for(let z of [...world.zombies]){if(z.userData.dead)continue;let vx=player.position.x-z.position.x,vz=player.position.z-z.position.z,d=Math.hypot(vx,vz);if(d>1.1){z.position.x+=vx/d*z.userData.speed*dt;z.position.z+=vz/d*z.userData.speed*dt;z.rotation.y=Math.atan2(vx,vz);z.position.y=Math.abs(Math.sin(world.elapsed*5+z.position.x))*.035}z.userData.attack-=dt;if(d<1.4&&z.userData.attack<=0){world.hp-=z.userData.type==='military'?12:9;z.userData.attack=1.2;toast(z.userData.type==='military'?'Military infected hit you!':'An infected got you!');if(world.hp<=0)endGame();updateHud()}}
 for(let i=world.drops.length-1;i>=0;i--){const d=world.drops[i];d.group.rotation.y+=dt;d.life-=dt;if(d.life<=0){scene.remove(d.group);world.drops.splice(i,1)}}pickup();let shop=nearShop();$('#interactBtn').textContent=shop?'TRADE':'USE';if(world.food>0&&world.hp<75)$('#interactBtn').textContent='EAT';if(Math.floor(world.elapsed*2)%2===0)updateHud();
 camera.position.set(player.position.x,player.position.y+15,player.position.z+17);camera.lookAt(player.position.x,0,player.position.z);camera.position.y=15;camera.position.z=player.position.z+17;
}
function blocked(x,z){return world.obstacles.some(o=>Math.hypot(x-o.x,z-o.z)<o.r+.35)}
function endGame(){dead=true;$('#daysSurvived').textContent=world.day;$('#death').classList.add('open')}
function restart(){location.reload()}
function animate(){requestAnimationFrame(animate);const dt=Math.min(clock.getDelta(),.05);update(dt);renderer.render(scene,camera)}function resize(){if(!renderer)return;camera.aspect=innerWidth/innerHeight;camera.updateProjectionMatrix();renderer.setSize(innerWidth,innerHeight)}

function startGame(){if(gameStarted)return;gameStarted=true;$('#intro').style.display='none';toast('The Corner Store and Field Pharmacy are inside the camp');updateHud()}
$('#play').addEventListener('click',startGame);$('#restart').addEventListener('click',restart);$('#attackBtn').addEventListener('pointerdown',e=>{e.preventDefault();attack()});$('#interactBtn').addEventListener('pointerdown',e=>{e.preventDefault();interact()});$('#cycleBtn').addEventListener('pointerdown',e=>{e.preventDefault();setWeapon((world.active+1)%4)});
window.addEventListener('keydown',e=>{keys[e.code]=true;if(['Space','ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(e.code))e.preventDefault();if(e.repeat)return;if(e.code==='Space')attack();if(e.code==='KeyE')interact();if(e.code==='Digit1')setWeapon(0);if(e.code==='Digit2')setWeapon(1);if(e.code==='Digit3')setWeapon(2);if(e.code==='Digit4')setWeapon(3);if(e.code==='Escape'&&paused)closeShop()});window.addEventListener('keyup',e=>keys[e.code]=false);window.addEventListener('blur',()=>Object.keys(keys).forEach(k=>keys[k]=false));
for(let i=0;i<4;i++)$('#slot'+i).addEventListener('click',()=>setWeapon(i));
let stickPointer=null;const stick=$('#stick');stick.addEventListener('pointerdown',e=>{stickPointer=e.pointerId;stick.setPointerCapture(e.pointerId);stickMove(e)});stick.addEventListener('pointermove',e=>{if(e.pointerId===stickPointer)stickMove(e)});function stickMove(e){let r=stick.getBoundingClientRect(),x=e.clientX-(r.left+r.width/2),y=e.clientY-(r.top+r.height/2),d=Math.hypot(x,y),max=r.width*.34;if(d>max){x=x/d*max;y=y/d*max}moveVec.set(x/max,y/max)}function stopStick(e){if(e.pointerId===stickPointer){stickPointer=null;moveVec.set(0,0)}}stick.addEventListener('pointerup',stopStick);stick.addEventListener('pointercancel',stopStick);
$('#shop').addEventListener('contextmenu',e=>e.preventDefault());
setup();
</script>
</body></html>

