function makeZombie(type,x,z){let g=new THREE.Group();g.position.set(x,0,z);scene.add(g);let uniform=mat(type==='police'?'#526f8a':type==='military'?'#55684a':'#71816a'),skin=mat('#9aaa82'),pants=mat('#4d5148');box(g,0,1.05,0,.55,.75,.34,uniform);cyl(g,-.14,.35,0,.2,.17,.65,pants);cyl(g,.14,.35,0,.2,.17,.65,pants);ball(g,0,1.67,0,.25,skin);box(g,0,1.54,.1,.34,.08,.28,mat('#382f2a'));for(let s of [-1,1]){let a=box(g,s*.37,1.05,.14,.16,.62,.16,uniform);a.rotation.x=-.5}if(type==='police'){cyl(g,0,1.89,0,.21,.21,.12,mat('#2f4354'));box(g,0,1.82,.02,.32,.08,.34,mat('#2f4354'))}if(type==='military')box(g,0,1.88,0,.42,.13,.36,mat('#343f32'));g.userData={type,hp:type==='regular'?42:58,speed:type==='regular'?.95:type==='police'?1.08:1.18,attack:rand(.3,1.5),dead:false};zombies.push(g);return g}
function spawn(){let a=rand(0,6.28),r=rand(19,31),x=clamp(player.position.x+Math.cos(a)*r,-32,32),z=clamp(player.position.z+Math.sin(a)*r,-32,32),n=Math.random();makeZombie(n<.16?'military':n<.38?'police':'regular',x,z)}
function drop(type,x,z){let g=new THREE.Group();g.position.set(x,.3,z);scene.add(g);box(g,0,0,0,.4,.13,.16,mat(type==='shotgun'?'#d9b866':type==='rifle'?'#a8c97b':'#e9dcb6'));ball(g,0,.22,0,.12,mat('#e9dcb6'));drops.push({type,x,z,g,life:40})}
function closeShop(){paused=false;$('#shop').classList.remove('open')}$('#closeShop').onclick=closeShop;$('#shop').addEventListener('pointerdown',e=>{if(e.target===$('#shop'))closeShop()});
const stock={market:[['🥫','Trail rations','A meal restores 35 vitality',8,'food'],['🔋','Ammo bundle','8 rounds for found weapons',12,'ammo'],['🧃','Energy tonic','Restore 45 stamina',7,'stamina']],pharmacy:[['🩹','Medkit','Restore 55 vitality',14,'med'],['💉','Field dressing','Restore 25 vitality',7,'bandage'],['🧪','Adrenal shot','Restore 60 stamina',9,'stamina']]};
function nearShop(){let best=null,d=9;for(const s of shops){let n=Math.hypot(player.position.x-s.x,player.position.z-s.z);if(n<d){best=s;d=n}}return d<5.4?best:null}
function openShop(s){if(!s){toast('Get closer to a shop to trade');return}paused=true;$('#shoplabel').textContent=s.type==='market'?'SAFE ZONE · MARKET':'SAFE ZONE · PHARMACY';$('#shopname').textContent=s.type==='market'?'The Corner Store':'Field Pharmacy';$('#shopcopy').textContent=s.type==='market'?'Trade with Mara before the sun drops. Supplies keep you moving; ammo keeps them down.':'Jules has patched up half the valley. Keep your health above zero.';let root=$('#goods');root.innerHTML='';for(const i of stock[s.type]){let row=document.createElement('div');row.className='good';row.innerHTML=`<span class="emoji">${i[0]}</span><div class="desc"><strong>${i[1]}</strong><small>${i[2]} · ¢${i[3]}</small></div><button class="buy" ${coins<i[3]?'disabled':''}>BUY</button>`;row.querySelector('button').onclick=()=>{if(coins<i[3])return;coins-=i[3];if(i[4]==='food')food++;if(i[4]==='ammo')ammo+=8;if(i[4]==='stamina')stamina=clamp(stamina+60,0,100);if(i[4]==='med')hp=clamp(hp+55,0,100);if(i[4]==='bandage')hp=clamp(hp+25,0,100);updateHud();toast(i[1]+' acquired');openShop(s)};root.appendChild(row)}$('#shop').classList.add('open');updateHud()}
function interact(){let s=nearShop();if(s)openShop(s);else if(food&&hp<94){food--;hp=clamp(hp+35,0,100);updateHud();toast('Rations eaten · +35 vitality')}else toast('No shop nearby · find a storefront')}
let toastTimer;function toast(t){let e=$('#toast');e.textContent=t;e.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>e.classList.remove('show'),1800)}
function updateHud(){let h=Math.round(hp);$('#hptext').textContent=h+' / 100';$('#hpbar').style.width=h+'%';$('#sttext').textContent=Math.round(stamina)+'%';$('#stbar').style.width=stamina+'%';$('#coins').textContent=coins;$('#shopcoins').textContent=coins;$('#foodcount').textContent=food;$('#shotcount').textContent=shotgun;$('#riflecount').textContent=rifle;$('#slot1').style.opacity=shotgun?1:.48;$('#slot2').style.opacity=rifle?1:.48;let b=biomeAt(player.position.x,player.position.z);$('#biome').innerHTML=(b==='Pinewood'?'🌲':b==='Ashlands'?'🌋':'🌿')+' <b>'+b+'</b>';for(let i=0;i<4;i++)$('#slot'+i).classList.toggle('active',active===i)}
function select(n){active=n;if(n===1&&!shotgun){toast('Find a police zombie for a shotgun');active=0}if(n===2&&!rifle){toast('Find a military zombie for a rifle');active=0}if(n===3&&!food){toast('No rations left');active=0}updateHud()}
function target(range){let found=null,d0=range;for(const z of zombies){let d=Math.hypot(z.position.x-player.position.x,z.position.z-player.position.z);if(d<d0){d0=d;found=z}}return found}
function damage(z,n){if(!z||z.userData.dead)return;z.userData.hp-=n;z.scale.set(1.12,.92,1.12);setTimeout(()=>{if(z.parent&&!z.userData.dead)z.scale.set(1,1,1)},100);if(z.userData.hp<=0){z.userData.dead=true;let type=z.userData.type,x=z.position.x,zz=z.position.z;scene.remove(z);zombies.splice(zombies.indexOf(z),1);coins+=type==='military'?6:type==='police'?4:2;toast(type==='military'?'Military infected down · +¢6':type==='police'?'Officer down · +¢4':'Infected down · +¢2');if(type==='police'&&Math.random()<.32)drop('shotgun',x,zz);if(type==='military'&&Math.random()<.31)drop('rifle',x,zz);if(Math.random()<.22)drop('food',x,zz);updateHud()}}
let attackWait=0;function attack(){if(!gameStarted||dead||paused)return;if(active===3){if(food){food--;hp=clamp(hp+35,0,100);stamina=clamp(stamina+15,0,100);toast('Rations eaten · +35 vitality');updateHud()}else toast('Out of rations');return}if(active===1||active===2){if(!shotgun&&!rifle){select(0);return}if(!ammo){toast('Out of ammo · visit the Corner Store');return}ammo--;let t=target(active===1?15:21);if(t){damage(t,active===1?48:38);if(active===1)for(const z of [...zombies])if(Math.hypot(z.position.x-t.position.x,z.position.z-t.position.z)<3)damage(z,22)}else toast('Shot missed · move closer');updateHud();return}if(attackWait>0)return;attackWait=.48;let t=target(3.2);if(t)damage(t,30);else toast('Nothing in reach')}
function pickup(){for(let i=drops.length-1;i>=0;i--){let d=drops[i];if(Math.hypot(player.position.x-d.x,player.position.z-d.z)<1.5){if(d.type==='shotgun'){shotgun=1;active=1;toast('POLICE SHOTGUN · weapon unlocked')}else if(d.type==='rifle'){rifle=1;active=2;toast('ASSAULT RIFLE · weapon unlocked')}else{food++;toast('Rations salvaged')}scene.remove(d.g);drops.splice(i,1);updateHud()}}}

